#include "ObjectPaletteAdapter3D.h"
#include <cmath>
using namespace Aevrynd;
namespace GameplayLab {
bool ObjectPaletteAdapter3D::Project(Ray3D ray){if(std::abs(ray.direction.y)<.0001f)return false;const float t=-ray.origin.y/ray.direction.y;if(t<0||t>200)return false;Vec3 p=ray.origin+ray.direction*t;p.x=std::round(p.x*.5f)*2;p.z=std::round(p.z*.5f)*2;p.y=.5f;preview_.position=p;preview_.valid=!collision_.OverlapsBox(p,{.48f,.48f,.48f});if(preview_.valid){++stats_.validPreviews;lastValid_=preview_.position;}else{++stats_.collisionRejected;lastInvalid_=preview_.position;}return true;}
bool ObjectPaletteAdapter3D::Begin(Ray3D ray,PaletteCategory category){preview_={true,false,{},0,category};rules_.SetPaletteCategory(category);++stats_.previews;return Project(ray);}
bool ObjectPaletteAdapter3D::PreviewAt(Vec3 position,PaletteCategory category){preview_={true,!collision_.OverlapsBox(position,{.48f,.48f,.48f}),position,0,category};rules_.SetPaletteCategory(category);++stats_.previews;if(preview_.valid){++stats_.validPreviews;lastValid_=position;}else{++stats_.collisionRejected;lastInvalid_=position;}return preview_.valid;}
bool ObjectPaletteAdapter3D::PlaceAt(Vec3 position,PaletteCategory category){preview_={true,!collision_.OverlapsBox(position,{.48f,.48f,.48f}),position,0,category};rules_.SetPaletteCategory(category);++stats_.previews;if(preview_.valid){++stats_.validPreviews;lastValid_=preview_.position;}else{++stats_.collisionRejected;lastInvalid_=preview_.position;}return Commit();}
bool ObjectPaletteAdapter3D::Update(Ray3D ray,float delta){if(!preview_.active)return false;preview_.rotation=std::round((preview_.rotation+delta*.2617994f)/.2617994f)*.2617994f;return Project(ray);}
bool ObjectPaletteAdapter3D::Commit(){if(!preview_.active||!preview_.valid)return false;const bool dynamic=preview_.category==PaletteCategory::Physics;if(!rules_.Place(preview_.position,dynamic))return false;const auto& placed=rules_.Entities().back();const auto id=placed.id;RigidBodySettings3D body{};body.type=dynamic?RigidBodyType3D::Dynamic:RigidBodyType3D::Static;body.transform.position=placed.position;body.transform.rotation={0,placed.rotation,0};std::vector<SceneEntity3D> created;SceneEntityDefinition3D definition{};definition.transform=SceneTransformComponent3D{body.transform};const auto handle=physics_.CreateBody(body);const auto collider=collision_.CreateBox({{placed.position,{.5f,.5f,.5f}},4,0xffffffffu,id,false});const bool sceneCreated=scene_.CreateBatchAtomic(std::span<const SceneEntityDefinition3D>{&definition,1},created);if(!handle||!collider||!sceneCreated||created.size()!=1){if(handle)physics_.DestroyBody(handle);if(collider)collision_.Destroy(collider);if(!created.empty())scene_.DestroyBatchAtomic(created);rules_.RollbackLastPlacement(id);return false;}bodies_.emplace(id,handle);colliders_.emplace(id,collider);sceneEntities_.emplace(id,created.front());++stats_.commits;preview_={};return true;}
void ObjectPaletteAdapter3D::Cancel(){if(preview_.active)++stats_.cancels;preview_={};}
bool ObjectPaletteAdapter3D::Delete(std::uint64_t id){auto f=bodies_.find(id);auto s=sceneEntities_.find(id);if(f==bodies_.end()||s==sceneEntities_.end()||!scene_.Alive(s->second)||!rules_.Delete(id))return false;physics_.DestroyBody(f->second);bodies_.erase(f);if(const auto c=colliders_.find(id);c!=colliders_.end()){collision_.Destroy(c->second);colliders_.erase(c);}scene_.Destroy(s->second);sceneEntities_.erase(s);++stats_.deletes;return true;}
bool ObjectPaletteAdapter3D::Reconcile(){std::unordered_map<std::uint64_t,const Entity*> desired;for(const auto& entity:rules_.Entities())desired.emplace(entity.id,&entity);struct Staged{std::uint64_t id{};RigidBodyHandle3D body{};ColliderHandle3D collider{};SceneEntity3D scene{};};std::vector<Staged> staged;for(const auto& [id,entity]:desired){if(bodies_.contains(id))continue;RigidBodySettings3D body{};body.type=entity->dynamic?RigidBodyType3D::Dynamic:RigidBodyType3D::Static;body.transform.position=entity->position;body.transform.rotation={0,entity->rotation,0};Staged item{id,physics_.CreateBody(body),collision_.CreateBox({{entity->position,{.5f,.5f,.5f}},4,0xffffffffu,id,false}),{}};SceneEntityDefinition3D definition{};definition.transform=SceneTransformComponent3D{body.transform};std::vector<SceneEntity3D> created;const bool sceneCreated=scene_.CreateBatchAtomic(std::span<const SceneEntityDefinition3D>{&definition,1},created);if(sceneCreated&&created.size()==1)item.scene=created.front();if(!item.body||!item.collider||!item.scene){if(item.body)physics_.DestroyBody(item.body);if(item.collider)collision_.Destroy(item.collider);if(item.scene)scene_.Destroy(item.scene);for(const auto& value:staged){physics_.DestroyBody(value.body);collision_.Destroy(value.collider);scene_.Destroy(value.scene);}return false;}staged.push_back(item);}for(auto it=bodies_.begin();it!=bodies_.end();){if(desired.contains(it->first)){++it;continue;}const auto id=it->first;physics_.DestroyBody(it->second);if(const auto c=colliders_.find(id);c!=colliders_.end()){collision_.Destroy(c->second);colliders_.erase(c);}if(const auto s=sceneEntities_.find(id);s!=sceneEntities_.end()){scene_.Destroy(s->second);sceneEntities_.erase(s);}it=bodies_.erase(it);}for(const auto& value:staged){bodies_.emplace(value.id,value.body);colliders_.emplace(value.id,value.collider);sceneEntities_.emplace(value.id,value.scene);}return true;}
bool ObjectPaletteAdapter3D::Undo(){if(!rules_.Undo())return false;if(!Reconcile()){rules_.Redo();Reconcile();return false;}++stats_.undo;return true;}
bool ObjectPaletteAdapter3D::Redo(){if(!rules_.Redo())return false;if(!Reconcile()){rules_.Undo();Reconcile();return false;}++stats_.redo;return true;}
bool ObjectPaletteAdapter3D::SyncDynamicTransforms(){for(const auto& entity:rules_.Entities()){if(!entity.dynamic)continue;const auto body=Body(entity.id);const auto collider=Collider(entity.id);const auto sceneEntity=SceneEntity(entity.id);const auto* state=physics_.GetBody(body);if(!state||!collider||!sceneEntity)return false;const auto& transform=state->settings.transform;if(!scene_.SetTransform(sceneEntity,SceneTransformComponent3D{transform})||!collision_.UpdateBox(collider,{{transform.position,{.5f,.5f,.5f}},4,0xffffffffu,entity.id,false}))return false;}return true;}
void ObjectPaletteAdapter3D::Clear(){for(auto [id,b]:bodies_){(void)id;physics_.DestroyBody(b);}for(auto [id,c]:colliders_){(void)id;collision_.Destroy(c);}for(auto [id,e]:sceneEntities_){(void)id;scene_.Destroy(e);}bodies_.clear();colliders_.clear();sceneEntities_.clear();rules_.Reset();preview_={};}
}
